","inline":true,"children":[{"text":""}]},{"text":""}]},{"type":"p","children":[{"text":""}]},{"type":"p","children":[{"text":"Zunächst berechnet man den Erwartungswert der Einnahmen bei Verkauf von einem Sack."}]},{"type":"p","children":[{"text":""},{"type":"math","src":"E(X)=32\cdot0,15+26\cdot 0,32+30\cdot 0,08+28,50 \cdot 0,42+20\cdot 0,03","inline":true,"children":[{"text":""}]},{"text":""}]},{"type":"p","children":[{"text":""},{"type":"math","src":"E(X)=28,09","inline":true,"children":[{"text":""}]},{"text":""}]},{"type":"p","children":[{"text":"Wenn der Großhändler "},{"type":"math","src":"120","inline":true,"children":[{"text":""}]},{"text":" Säcke verkauft, so hat er einen Umsatz von "},{"type":"math","src":"120\cdot 28{,}09=3370{,}08","inline":true,"children":[{"text":""}]},{"text":""}]},{"type":"p","children":[{"text":"Sein Gewinn beträgt "},{"type":"math","src":"30","inline":true,"children":[{"text":""}]},{"text":"% vom Umsatz: "}]},{"type":"p","children":[{"text":"Also ist der Gewinn "},{"type":"math","src":"1011{,}24 ","inline":true,"children":[{"text":""}]},{"text":" Euro."}]}],"id":"96ce82a3-8a7e-49ce-8f45-5709a66cb858"},"steps":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{}]}],"id":"32dfcd21-9c0c-426b-9347-fbf6ed00e4b6"}],"id":"7c4218c3-0133-41b3-bb0b-9bf1c9534790"}},"id":"644c5761-d6f8-4c60-b44c-b5662d772118"}},"id":"201985-exercise-child"}]},"id":"574476da-9a26-471c-a511-78bd9f1ccacc"}}
